#include <stdio.h>

int main(int argc, char **argv)
{
    long long a=0, b=0, m=0, n=0, ans=0, c=0, i;
    scanf("%lld%lld%lld%lld", &a, &b, &m, &n);

    ans = a+b;
    for(i=3; i<=n; i++)
    {
        c = a+b;
        ans += c;
        a = b;
        b = c;
        if(c>=m) break;
    }

    printf("%lld\n", ans);
    return 0;
}

#include <stdio.h>

int main(int argc, char **argv)
{
    int n, i, j;
    scanf("%d", &n);
    for(i=1; i<=(n+1)/2-1; i++)
    {
        printf("|");
        for(j=2; j<=n-1; j++)
        {
            printf("a");
        }
        printf("|\n");
    }

    printf("|");
    for(j=2; j<=n-1; j++)
    {
        printf("-");
    }
    printf("|\n");

    for(i=(n+1)/2+1; i<=n; i++)
    {
        printf("|");
        for(j=2; j<=n-1; j++)
        {
            printf("a");
        }
        printf("|\n");
    }
    return 0;
}
